 import { h, render } from 'https://esm.sh/preact';
 import { useState } from 'https://esm.sh/preact/hooks';
 import htm from 'https://esm.sh/htm';

 const html = htm.bind(h);

 const QUIZ_QUESTIONS = [
   {
     id: 'q1',
     question: 'Which of these are statically typed languages?',
     helpText: 'Statically typed languages perform type checking at compile-time.',
     options: [
       { id: 'q1-o1', label: 'Java', value: 'java' },
       { id: 'q1-o2', label: 'Python', value: 'python' },
       { id: 'q1-o3', label: 'C++', value: 'cpp' },
       { id: 'q1-o4', label: 'Ruby', value: 'ruby' },
     ],
   },
   {
     id: 'q2',
     question: 'Which languages are primarily used for web development?',
     options: [
       { id: 'q2-o1', label: 'JavaScript', value: 'javascript' },
       { id: 'q2-o2', label: 'Rust', value: 'rust' },
       { id: 'q2-o3', label: 'PHP', value: 'php' },
       { id: 'q2-o4', label: 'C#', value: 'csharp' },
     ],
   },
   {
     id: 'q3',
     question: 'Which of these were first released before the year 2000?',
     options: [
       { id: 'q3-o1', label: 'Python', value: 'python' },
       { id: 'q3-o2', label: 'C#', value: 'csharp' },
       { id: 'q3-o3', label: 'Java', value: 'java' },
       { id: 'q3-o4', label: 'TypeScript', value: 'typescript' },
     ],
   },
 ];

 const CheckboxOption = ({ option, name, checked, onChange }) => {
   return html`
     <div class="checkbox-option">
       <input
         type="checkbox"
         id="${option.id}"
         name="${name}"
         value="${option.value}"
         checked=${checked}
         onChange=${(e) => onChange(option.value, e.target.checked)}
       />
       <label for="${option.id}">${option.label}</label>
     </div>
   `;
 };

 const Question = ({ data, selections, onSelectionChange }) => {
   const helpId = data.helpText ? `${data.id}-help` : null;

   return html`
     <div class="form-field">
       <fieldset aria-describedby="${helpId}">
         <legend>${data.question}</legend>
         ${data.helpText && html`<p id="${helpId}" class="help-text">${data.helpText}</p>`}
         ${data.options.map(
           (option) => html`
             <${CheckboxOption}
               key=${option.id}
               option=${option}
               name="${data.id}"
               checked=${selections.includes(option.value)}
               onChange=${(value, isChecked) => onSelectionChange(data.id, value, isChecked)}
             />
           `
         )}
       </fieldset>
     </div>
   `;
 };

 const App = () => {
   const [selections, setSelections] = useState({
     q1: [],
     q2: [],
     q3: [],
   });
   const [submitted, setSubmitted] = useState(false);

   const handleSelectionChange = (questionId, value, isChecked) => {
     setSelections((prev) => {
       const current = prev[questionId];
       const next = isChecked
         ? [...current, value]
         : current.filter((v) => v !== value);
       return { ...prev, [questionId]: next };
     });
   };

   const handleSubmit = (e) => {
     e.preventDefault();
     setSubmitted(true);
     console.log('Quiz Selections:', selections);
   };

   return html`
     <main>
       <header>
         <h1>Computer Languages Quiz</h1>
         <p class="subtitle">Test your knowledge of programming languages.</p>
       </header>

       <form onSubmit=${handleSubmit}>
         ${QUIZ_QUESTIONS.map(
           (q) => html`
             <${Question}
               key=${q.id}
               data=${q}
               selections=${selections[q.id]}
               onSelectionChange=${handleSelectionChange}
             />
           `
         )}

         <button type="submit">Submit Answers</button>
       </form>

       ${submitted &&
       html`
         <div class="results" role="status">
           <strong>Thank you!</strong> Your answers have been submitted successfully.
         </div>
       `}
     </main>
   `;
 };

 render(html`<${App} />`, document.getElementById('app'));

')

