const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Log browser console messages
  page.on('console', msg => console.log('BROWSER LOG:', msg.text()));
  page.on('pageerror', err => console.log('BROWSER ERROR:', err.message));

  // Use absolute path for file:// URL
  const filePath = 'file://' + path.resolve('index.html');
  await page.goto(filePath, { waitUntil: 'load' });

  // Inject axe-core
  const axeSource = fs.readFileSync('/tmp/axe.min.js', 'utf8');
  await page.evaluate(axeSource);

  // Debug: print rendered HTML
  const content = await page.content();
  console.log("RENDERED HTML LENGTH:", content.length);
  console.log("APP DIV CONTENT:", await page.innerHTML('#app'));

  // Run axe
  const results = await page.evaluate(async () => {
    // Wait for the app to render
    await new Promise(resolve => setTimeout(resolve, 1000));
    return await window.axe.run();
  });

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, nodes: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, impact: v.impact, help: v.help, nodes: v.nodes.map(n => n.target) }))
  }, null, 2));

  await browser.close();
  process.exit(wcag.length > 0 ? 1 : 0);
})();
